// Seven-card poker evaluator.
//
// Card encoding: integer 0..51 where rank = card >> 2 (0 = deuce ... 12 = ace),
// suit = card & 3 (0 clubs, 1 diamonds, 2 hearts, 3 spades).
//
// eval7 finds the best 5-card hand among all C(7,5) combinations, reusing
// evaluate5 internally. Hand strength is a single comparable number:
// category * 13^5 + packed ordered tiebreak ranks (base 13, zero padded).

export type Card = number;

export const RANK_CHARS = '23456789TJQKA';
export const SUIT_CHARS = 'cdhs';

/** Parse a card like "As", "Td", "2c". */
export function card(str: string): Card {
  if (str.length !== 2) throw new Error(`bad card: ${str}`);
  const r = RANK_CHARS.indexOf(str[0].toUpperCase());
  const s = SUIT_CHARS.indexOf(str[1].toLowerCase());
  if (r < 0 || s < 0) throw new Error(`bad card: ${str}`);
  return r * 4 + s;
}

/** Parse cards given as a concatenated string, e.g. "AhKh" -> [card Ah, card Kh]. */
export function parseCards(str: string): Card[] {
  if (str.length % 2 !== 0) throw new Error(`bad card string: ${str}`);
  const out: Card[] = [];
  for (let i = 0; i < str.length; i += 2) out.push(card(str.slice(i, i + 2)));
  return out;
}

export function cardToString(c: Card): string {
  return RANK_CHARS[c >> 2] + SUIT_CHARS[c & 3];
}

export const CATEGORY_NAMES = [
  'high card',
  'pair',
  'two pair',
  'trips',
  'straight',
  'flush',
  'full house',
  'quads',
  'straight flush',
] as const;

const PAD = 0; // padding for short tiebreak lists (lowest possible value)

/**
 * Evaluate exactly 5 cards. Returns a comparable score; higher is better.
 * Equal scores mean an exact tie in hand strength.
 */
export function evaluate5(cards: Card[]): number {
  if (cards.length !== 5) throw new Error('evaluate5 needs exactly 5 cards');

  const rankCount = new Array<number>(13).fill(0);
  const suitCount = new Array<number>(4).fill(0);
  for (const c of cards) {
    rankCount[c >> 2]++;
    suitCount[c & 3]++;
  }

  let flush = false;
  for (let s = 0; s < 4; s++) if (suitCount[s] === 5) flush = true;

  // Unique ranks descending.
  const uniq: number[] = [];
  for (let r = 12; r >= 0; r--) if (rankCount[r] > 0) uniq.push(r);

  let straightHigh = -1;
  if (uniq.length === 5) {
    if (uniq[0] - uniq[4] === 4) straightHigh = uniq[0];
    else if (uniq[0] === 12 && uniq[1] === 3) straightHigh = 3; // wheel A-5
  }

  // Groups sorted by count desc, then rank desc.
  const groups: Array<{ r: number; n: number }> = [];
  for (let r = 12; r >= 0; r--) if (rankCount[r] > 0) groups.push({ r, n: rankCount[r] });
  groups.sort((a, b) => b.n - a.n || b.r - a.r);

  let cat: number;
  let tie: number[];
  if (flush && straightHigh >= 0) {
    cat = 8;
    tie = [straightHigh];
  } else if (groups[0].n === 4) {
    cat = 7;
    tie = [groups[0].r, groups[1].r];
  } else if (groups[0].n === 3 && groups[1].n >= 2) {
    cat = 6;
    tie = [groups[0].r, groups[1].r];
  } else if (flush) {
    cat = 5;
    tie = uniq.slice();
  } else if (straightHigh >= 0) {
    cat = 4;
    tie = [straightHigh];
  } else if (groups[0].n === 3) {
    cat = 3;
    tie = [groups[0].r, groups[1].r, groups[2].r];
  } else if (groups[0].n === 2 && groups[1].n === 2) {
    cat = 2;
    tie = [groups[0].r, groups[1].r, groups[2].r];
  } else if (groups[0].n === 2) {
    cat = 1;
    tie = [groups[0].r, groups[1].r, groups[2].r, groups[3].r];
  } else {
    cat = 0;
    tie = uniq.slice();
  }

  let v = cat;
  for (let i = 0; i < 5; i++) v = v * 13 + (i < tie.length ? tie[i] : PAD);
  return v;
}

/** All C(7,5) = 21 index combinations of 7 choose 5. */
const COMBOS_7_5: ReadonlyArray<readonly [number, number, number, number, number]> = (() => {
  const out: Array<[number, number, number, number, number]> = [];
  for (let a = 0; a < 7; a++)
    for (let b = a + 1; b < 7; b++)
      for (let c = b + 1; c < 7; c++)
        for (let d = c + 1; d < 7; d++)
          for (let e = d + 1; e < 7; e++) out.push([a, b, c, d, e]);
  return out;
})();

/**
 * Evaluate the best 5-card hand made from exactly 7 cards
 * (e.g. two hole cards + five board cards).
 */
export function eval7(cards: Card[]): number {
  if (cards.length !== 7) throw new Error('eval7 needs exactly 7 cards');
  let best = -1;
  for (const [a, b, c, d, e] of COMBOS_7_5) {
    const s = evaluate5([cards[a], cards[b], cards[c], cards[d], cards[e]]);
    if (s > best) best = s;
  }
  return best;
}

