// Seeded Monte Carlo equity: AA vs 22 all-in preflop.
//
// Uses a mulberry32 PRNG so results are fully reproducible: the same seed
// yields bit-identical output across runs.

import { Card, card, eval7, parseCards } from './eval7.js';

export type Rng = () => number;

/** mulberry32: tiny, fast, seedable PRNG returning floats in [0, 1). */
export function mulberry32(seed: number): Rng {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export interface EquityResult {
  deals: number;
  wins: number;
  splits: number;
  losses: number;
  /** Win probability counting each split pot as half a win, in [0, 1]. */
  equity: number;
}

/**
 * Monte Carlo the all-in preflop matchup heroHand vs villainHand
 * (each a 2-card string like "AsAh"). Dead cards are removed from the deck,
 * the remaining cards are Fisher-Yates shuffled with the seeded RNG and five
 * are dealt as the board. Ties on the best-5-of-7 rank split the pot.
 */
export function simulate(
  heroHandStr: string,
  villainHandStr: string,
  deals: number,
  seed: number,
): EquityResult {
  const rng = mulberry32(seed);
  const hero: Card[] = parseCards(heroHandStr);
  const villain: Card[] = parseCards(villainHandStr);

  const dead = new Set<number>([...hero, ...villain]);
  const deck: Card[] = [];
  for (let c = 0; c < 52; c++) if (!dead.has(c)) deck.push(c);

  let wins = 0;
  let splits = 0;
  let losses = 0;

  for (let i = 0; i < deals; i++) {
    // Partial Fisher-Yates: only draw the 5 board cards we need.
    for (let j = 0; j < 5; j++) {
      const k = j + Math.floor(rng() * (deck.length - j));
      const tmp = deck[j];
      deck[j] = deck[k];
      deck[k] = tmp;
    }
    const board = [deck[0], deck[1], deck[2], deck[3], deck[4]];

    const hs = eval7([...hero, ...board]);
    const vs = eval7([...villain, ...board]);
    if (hs > vs) wins++;
    else if (hs === vs) splits++;
    else losses++;
  }

  return {
    deals,
    wins,
    splits,
    losses,
    equity: (wins + splits / 2) / deals,
  };
}

/** Convenience wrapper for the classic AA vs 22 all-in preflop sim. */
export function simulateAAvs22(deals = 20000, seed = 42): EquityResult {
  return simulate('AsAh', '2c2d', deals, seed);
}

// Allow running directly: `node equity.ts`
if (process.argv[1] && process.argv[1].endsWith('equity.ts')) {
  const r = simulateAAvs22(20000, 42);
  console.log(
    `AA vs 22 over ${r.deals} deals (seed 42): ` +
      `wins=${r.wins} splits=${r.splits} losses=${r.losses} equity=${r.equity}`,
  );
}

